mapper.select:
SELECT l.log_id, l.business_name, l.log_type, l.dept_id, d.dept_name AS dept_name, l.oper_id, u.nickname AS oper_name, u.username AS username, l.request_url, l.request_params, l.execution_time, l.status, l.error_msg, l.ip, l.address, l.browser, l.track_id, l.oper_time FROM sys_log l LEFT JOIN sys_user u ON u.user_id = l.oper_id LEFT JOIN sys_dept d ON d.dept_id = l.dept_id
AND l.log_type = #{logType}
AND u.nickname LIKE CONCAT('%', #{operName}, '%')
AND u.username LIKE CONCAT('%', #{username}, '%')
AND l.request_url LIKE CONCAT('%', #{requestUrl}, '%')
AND l.status = #{status}
AND l.ip = #{ip}
AND l.track_id = #{trackId}
AND l.oper_time >= #{startTime}
AND l.oper_time <= #{endTime}
ORDER BY l.oper_time DESC, l.log_id DESC
